const { expect } = require('chai');
const { io } = require('socket.io-client');
const request = require('supertest');
const User = require('../user/user-model');
const News = require('../database/news-model');
const Chat = require('../database/chat-record-model');
const server = require('./server-test');

// Generated by bcrypt-nodejs 0.0.3, the library used by the old server.
const legacyHash = '$2a$10$nCb4agIONfClrR00mqfIjuS6ULRRJyi1wKiwAg7tDxGsC/TKcJ8ta';

function response(socket, controller, type, data) {
    return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
            socket.off('message', listener);
            reject(new Error('Timed out waiting for ' + controller));
        }, 5000);
        function listener(message) {
            if (message.type !== controller) return;
            clearTimeout(timer);
            socket.off('message', listener);
            resolve(message.data);
        }
        socket.on('message', listener);
        socket.send({ controller, type, data });
    });
}

describe('modern runtime compatibility', function() {
    let socket;
    beforeEach(async function() {
        socket = io('http://127.0.0.1:' + server.app.httpServer.address().port, {
            transports: ['websocket'], reconnection: false
        });
        await new Promise((resolve, reject) => {
            socket.once('connect', resolve);
            socket.once('connect_error', reject);
        });
    });
    afterEach(async function() {
        socket.disconnect();
        await Promise.all([User.deleteMany({}), News.deleteMany({}), Chat.deleteMany({})]);
    });

    it('logs in with an unchanged legacy bcrypt hash and reuses its token', async function() {
        // A restore bypasses Mongoose casting and hooks, just like this raw insert.
        await User.collection.insertOne({ username: 'legacy', password: legacyHash });
        const login = await response(socket, 'auth', 'login', {
            username: 'legacy', password: 'legacy-brogue-password'
        });
        expect(login.result).to.equal('success');
        expect((await User.findOne({ username: 'legacy' })).password).to.equal(legacyHash);
        await response(socket, 'auth', 'logout', {});
        const tokenLogin = await response(socket, 'auth', 'login', { token: login.data.token });
        expect(tokenLogin.data.message).to.equal('logged-in');
        expect(tokenLogin.data.username).to.equal('legacy');
    });

    it('rejects an incorrect password for a legacy user', async function() {
        await User.collection.insertOne({ username: 'legacy', password: legacyHash });
        const result = await response(socket, 'auth', 'login', {
            username: 'legacy', password: 'wrong'
        });
        expect(result.result).to.equal('fail');
    });

    it('registers and authenticates a new account over Socket.IO 4', async function() {
        const credentials = { username: 'new-player', password: 'new-password', repeat: 'new-password' };
        expect((await response(socket, 'auth', 'register', credentials)).result).to.equal('success');
        const saved = await User.findOne({ username: credentials.username });
        expect(saved.password).not.to.equal(credentials.password);
        expect((await response(socket, 'auth', 'login', credentials)).data.message).to.equal('logged-in');
    });

    it('returns persisted chat history through Socket.IO 4', async function() {
        await Chat.create({ username: 'legacy', message: '<old message>' });
        const history = await response(socket, 'chat', 'lobbyHistory', {});
        expect(history.type).to.equal('history');
        expect(history.history[0].message).to.equal('&lt;old message&gt;');
    });

    it('serves news with dates and pagination on Express 5', async function() {
        await News.collection.insertOne({ date: new Date(), story: 'Restored story', seq: 17 });
        const result = await request(server.app).get('/api/news?page=1&limit=1').expect(200);
        expect(result.body.itemCount).to.equal(1);
        expect(result.body.data[0].story).to.equal('Restored story');
        expect(result.body.data[0].seq).to.equal(17);
    });
});
